native.harness:
#include <glob.h>
#include <cstdio>
#include <cstdlib>
#include <string>
#include <vector>
#include <algorithm>
static std::vector<std::string> globClockFiles(const std::string &pattern)
{
  glob_t g;
  std::vector<std::string> files;

  const int globRet = glob(pattern.c_str(), 0, NULL, &g);
  if (globRet == GLOB_NOSPACE)
  {
    std::fprintf(stderr, "Out of memory in clkcorr.C\n");
    std::exit(1);
  }
#ifdef GLOB_ABORTED
  if (globRet == GLOB_ABORTED)
  {
    std::fprintf(stderr, "Read error in clkcorr.C\n");
    std::exit(1);
  }
#endif
  if (globRet == 0)
  {
    for (char **pfname = g.gl_pathv; *pfname != NULL; ++pfname)
      files.push_back(*pfname);
  }
  globfree(&g);

  std::sort(files.begin(), files.end());
  return files;
}


int main(int argc,char**argv){if(argc!=2)return 2;for(const auto &p:globClockFiles(argv[1])){for(unsigned char c:p)std::printf("%02x",c);std::puts("");}}
